// Единственная нода, которая знает про Telegram. Для WhatsApp/Max заменяются триггер,
// эта нода и нода ответа — всё остальное работает с полями ниже.
const msg = $('Telegram Trigger').first().json.message || {};
const from = msg.from || {};
let text = (msg.text || '').trim();
if (msg.contact) text = `Мой телефон: ${msg.contact.phone_number}`;
if (/^\/start/.test(text)) text = 'Здравствуйте! Расскажите, какие есть курсы?';
return [{
  json: {
    channel: 'telegram',
    chatId: String(msg.chat?.id ?? ''),
    userName: [from.first_name, from.last_name].filter(Boolean).join(' '),
    userHandle: from.username ? '@' + from.username : '',
    text: text || '(пустое сообщение)',
  },
}];

const cfg = Object.fromEntries($('Config').all().map(i => [i.json.key, i.json.value]));
const n = $('Normalize (канал → общий формат)').first().json;
const courses = $('Knowledge Base').all().map(i => i.json);

// База небольшая (десятки курсов) — кладём её в промпт целиком, без векторного поиска
const kb = courses.map(c => [
  `[${c.course_id}] ${c.title}`,
  `  Для кого: ${c.audience}; город: ${c.city}; даты: ${c.dates}; формат: ${c.format}`,
  `  Стоимость: ${Number(c.price_rub).toLocaleString('ru-RU')} ₽; мест: ${c.seats}; лектор: ${c.lecturer}`,
  `  Программа: ${c.program}`,
].join('\n')).join('\n\n');

const policies = `Оплата: по счёту для клиник или онлайн по ссылке от менеджера. Бронь места — 3 рабочих дня после заявки.
Скидка 10 % при записи двух и более сотрудников одной клиники на один курс; другие скидки — только через менеджера.
Документы: сертификат учебного центра HELIOS. Баллы НМО бот не обещает — уточняет менеджер.
Отмена: возврат 100 % не позднее чем за 7 дней до начала; позже — перенос на другой поток.
Адреса: Сочи, ул. Навагинская; Москва — площадка партнёра. Точный адрес и проезд сообщает менеджер.`;

const system = `Ты — ИИ-консультант учебного центра HELIOS (зуботехническая лаборатория и обучение для стоматологов и зубных техников, Сочи/Москва).

ПРАВИЛА (нарушать нельзя):
1. Отвечай ТОЛЬКО по БАЗЕ ЗНАНИЙ и УСЛОВИЯМ ниже. Не выдумывай курсы, цены, даты, лекторов, скидки, адреса, баллы НМО.
2. Не давай медицинских рекомендаций и не называй цены на лечение (имплантация, протезирование, виниры для пациента и т. п.) — учебный центр этим не занимается.
3. Если ответа нет в базе — честно скажи, что таких данных у тебя нет, и предложи подключить менеджера.
4. Веди к записи: помоги выбрать курс, затем спроси имя и телефон. Платёжные данные не запрашивай — счёт и ссылку на оплату отправляет менеджер.
5. Стиль: коллегиальный и профессиональный, как между стоматологами; на «Вы»; кратко (до 6 строк); без восклицаний и лишних эмодзи.

ПЕРЕДАЧА МЕНЕДЖЕРУ (handoff.needed = true) — ровно один раз, когда:
- клиент хочет записаться/оплатить И уже назвал имя и телефон (reason "запись"); если телефона нет — сначала попроси его;
- вопрос вне базы и клиент согласен на менеджера или просит человека (reason "вопрос вне базы").
В остальных случаях handoff.needed = false. После передачи скажи, что менеджер свяжется в рабочее время.

ФОРМАТ ОТВЕТА — всегда один JSON-объект без текста вокруг:
{"reply": "текст клиенту", "handoff": {"needed": false, "reason": "", "name": "", "phone": "", "course": "", "summary": "1–2 предложения: что хочет клиент"}}

БАЗА ЗНАНИЙ — КУРСЫ:
${kb}

УСЛОВИЯ:
${policies}

Сегодня: ${$now.setZone('Europe/Moscow').toFormat('dd.MM.yyyy')}. Клиент в мессенджере: ${n.userName || 'без имени'} ${n.userHandle}.`;

return [{ json: { ...n, system, sessionId: `${n.channel}:${n.chatId}`, model: cfg.kb_model } }];

const out = String($input.first().json.output ?? '').replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '').trim();

// Модель иногда ломает JSON (лишняя «}», текст вокруг). Клиент не должен увидеть JSON никогда.
const tryParse = (s) => { try { return JSON.parse(s); } catch (e) { return null; } };
let data = null;
const start = out.indexOf('{');
if (start >= 0) {
  let s = out.slice(start);
  for (let i = 0; i < 6 && !data; i++) {
    data = tryParse(s);
    if (!data) s = s.replace(/[\s\S]$/, '');            // срезаем хвост по символу
  }
  if (!data) {
    const end = out.lastIndexOf('}');
    for (let e = end; e > start && !data; e = out.lastIndexOf('}', e - 1)) data = tryParse(out.slice(start, e + 1));
  }
}
if (!data) {
  // последний шанс: достаём reply регуляркой, иначе отдаём текст как есть (если это не JSON)
  const m = out.match(/"reply"\s*:\s*"((?:[^"\\]|\\.)*)"/);
  data = { reply: m ? tryParse('"' + m[1] + '"') : (start === 0 ? '' : out), handoff: { needed: false } };
}

const h = data.handoff || {};
return [{
  json: {
    reply: String(data.reply || 'Извините, не расслышал вопрос. Переформулируйте, пожалуйста.'),
    handoff: {
      needed: h.needed === true,
      reason: String(h.reason || ''),
      name: String(h.name || ''),
      phone: String(h.phone || '').replace(/[^\d+]/g, ''),
      course: String(h.course || ''),
      summary: String(h.summary || ''),
    },
  },
}];

const cfg = Object.fromEntries($('Config').all().map(i => [i.json.key, i.json.value]));
const b = $('Build Prompt').first().json;
const h = $('Parse Answer').first().json.handoff;
// Менеджеру нужно название курса, а не код: «C01» → «C01 — Цифровое моделирование…»
const code = (String(h.course || '').match(/C\d{2}/i) || [])[0];
const c = code && $('Knowledge Base').all().map(i => i.json).find(x => x.course_id === code.toUpperCase());
if (c) h.course = `${c.course_id} — ${c.title} (${c.city}, ${c.dates})`;
return [{
  json: {
    target: cfg.lead_target === 'bitrix' && cfg.bitrix_webhook ? 'bitrix' : 'sheets',
    bx: cfg.bitrix_webhook ? (cfg.bitrix_webhook.endsWith('/') ? cfg.bitrix_webhook : cfg.bitrix_webhook + '/') : '',
    sheetId: cfg.sheet_id,
    managerChatId: cfg.manager_chat_id,
    name: h.name || b.userName || 'Клиент из Telegram',
    phone: h.phone,
    course: h.course,
    reason: h.reason || 'запись',
    summary: h.summary,
    channel: b.channel,
    chatId: b.chatId,
    handle: b.userHandle,
    at: $now.setZone('Europe/Moscow').toFormat('dd.MM.yyyy HH:mm'),
  },
}];

