  COMMENTS: `Курс: ${$json.course || '—'}\nПричина: ${$json.reason}\nРезюме диалога: ${$json.summary}\nКанал: ${$json.channel} ${$json.handle} (chat_id ${$json.chatId})`,
} }) }}
